import {Button, ButtonProps} from '../src/Button';

import {generatePowerset} from '@react-spectrum/story-utils';
import type {Meta, StoryObj} from '@storybook/react';
import NewIcon from '../s2wf-icons/S2_Icon_New_20_N.svg';
import {ReactNode} from 'react';
import {shortName} from './utils';
import {StaticColorProvider} from '../stories/utils';
import {style} from '../style' with {type: 'macro'};
import {Text} from '../src/Content';
import {Example as WithWrapping} from '../stories/Button.stories';

const meta: Meta<typeof Button> = {
  component: Button,
  parameters: {
    chromaticProvider: {disableAnimations: true}
  },
  title: 'S2 Chromatic/Button'
};

export default meta;

let states = [
  {isQuiet: true},
  {isDisabled: true},
  {size: ['S', 'M', 'L', 'XL']},
  {staticColor: ['black', 'white']},
  {variant: ['accent', 'negative', 'primary', 'secondary']}
];

let combinations = generatePowerset(states);

let premiumStates = [{isDisabled: true}, {size: ['S', 'M', 'L', 'XL']}];

let premiumCombinations = generatePowerset(premiumStates);

let genaiStates = [{isDisabled: true}, {size: ['S', 'M', 'L', 'XL']}];

let genaiCombinations = generatePowerset(genaiStates);

let staticColorAutoStates = [
  {isQuiet: true},
  {isDisabled: true},
  {size: ['S', 'M', 'L', 'XL']},
  {staticColor: ['auto']},
  {variant: ['accent', 'negative', 'primary', 'secondary']}
];

let staticColorAutoCombinations = generatePowerset(staticColorAutoStates).filter(
  c => c.staticColor != null
);

const Template = (args: ButtonProps & {combos?: any[]}): ReactNode => {
  let {children, combos = combinations, variant, ...otherArgs} = args;
  return (
    <div
      className={style({
        display: 'grid',
        gridTemplateColumns: 'repeat(4, minmax(0, 250px))',
        gridAutoFlow: 'row',
        alignItems: 'center',
        justifyItems: 'start',
        gap: 24,
        width: '100vw'
      })}>
      {combos.map(c => {
        let fullComboName = Object.keys(c)
          .map(k => `${k}: ${c[k]}`)
          .join(' ');
        let key = Object.keys(c)
          .map(k => shortName(k, c[k]))
          .join(' ');
        if (!key) {
          key = 'default';
        }

        let finalVariant = c.variant ?? variant;
        let buttonProps = {...otherArgs, ...c, ...(finalVariant && {variant: finalVariant})};
        let button = (
          <Button data-testid={fullComboName} key={key} {...buttonProps}>
            {children ? children : key}
          </Button>
        );
        if (c.staticColor != null) {
          return (
            <StaticColorProvider key={`static-${key}`} staticColor={c.staticColor} hideColorPicker>
              {button}
            </StaticColorProvider>
          );
        }

        return button;
      })}
    </div>
  );
};

export const Default: StoryObj<typeof Button> = {
  render: args => <Template {...args} />
};

export const StaticColorAuto: StoryObj<typeof Button> = {
  render: args => <Template {...args} combos={staticColorAutoCombinations} />
};

export const WithIcon: StoryObj<typeof Button> = {
  render: args => <Template {...args} />,
  args: {
    children: (
      <>
        <NewIcon />
        <Text>Press me</Text>
      </>
    )
  }
};

export const IconOnly: StoryObj<typeof Button> = {
  render: args => <Template {...args} />,
  args: {
    children: <NewIcon />
  }
};

export const Premium: StoryObj<typeof Button> = {
  render: args => <Template {...args} combos={premiumCombinations} />,
  args: {
    children: 'Press me',
    variant: 'premium'
  }
};

export const PremiumWithIcon: StoryObj<typeof Button> = {
  render: args => <Template {...args} combos={premiumCombinations} />,
  args: {
    children: (
      <>
        <NewIcon />
        <Text>Press me</Text>
      </>
    ),
    variant: 'premium'
  }
};

export const PremiumIconOnly: StoryObj<typeof Button> = {
  render: args => <Template {...args} combos={premiumCombinations} />,
  args: {
    children: <NewIcon />,
    variant: 'premium'
  }
};

export const GenAI: StoryObj<typeof Button> = {
  render: args => <Template {...args} combos={genaiCombinations} />,
  args: {
    children: 'Press me',
    variant: 'genai'
  }
};

export const GenAIWithIcon: StoryObj<typeof Button> = {
  render: args => <Template {...args} combos={genaiCombinations} />,
  args: {
    children: (
      <>
        <NewIcon />
        <Text>Press me</Text>
      </>
    ),
    variant: 'genai'
  }
};

export const GenAIIconOnly: StoryObj<typeof Button> = {
  render: args => <Template {...args} combos={genaiCombinations} />,
  args: {
    children: <NewIcon />,
    variant: 'genai'
  }
};

export {WithWrapping};
